const body = $input.first().json.body || {};

// Check required fields
const hasFile = !!(body.file_url || body.file_base64);
const hasAction = !!body.action;

// If missing required fields, return error
if (!hasFile || !hasAction) {
  const missing = [];
  const errors = [];

  if (!hasFile) {
    missing.push('file');
    errors.push('Document requis (file_url ou file_base64)');
  }
  if (!hasAction) {
    missing.push('action');
    errors.push('Action requise');
  }

  return {
    json: {
      valid: false,
      can_proceed: false,
      missing: missing,
      errors: errors,
      questions: []
    }
  };
}

// Extract config
const action = body.action;
const params = body.params || {};
const userMessage = body.user_message || '';
const availableActions = body.available_actions || body.plugin_context?.available_actions || ['translate', 'summarize', 'process'];
const requiredParams = body.plugin_context?.required_params || { translate: ['target_language'], summarize: ['format'] };
const customActions = body.plugin_context?.custom_actions || {};

// Check if action is valid
const isProcessAction = action === 'process';
const isStandardAction = availableActions.includes(action);
const isCustomAction = Object.keys(customActions).includes(action);

if (!isProcessAction && !isStandardAction && !isCustomAction) {
  return {
    json: {
      valid: false,
      can_proceed: false,
      missing: [],
      errors: [`Action '${action}' non disponible. Actions valides: ${[...availableActions,
...Object.keys(customActions)].join(', ')}`],
      questions: []
    }
  };
}

if (isProcessAction && !userMessage) {
  return {
    json: {
      valid: false,
      can_proceed: false,
      missing: ['user_message'],
      errors: ['user_message requis pour action "process"'],
      questions: []
    }
  };
}


// Check required params for the action
const finalRequiredParams = customActions[action]?.required_params || requiredParams[action] || [];

const missingParams = [];
const questions = [];

const paramQuestions = {
  target_language: {
    question: 'Dans quelle langue veux-tu la traduction ?',
    type: 'text',
    examples: 'français, anglais, espagnol...'
  },
  format: {
    question: 'Quel format de synthèse souhaites-tu ?',
    type: 'choice',
    options: [
      { value: 'express', label: 'Résumé express (2-3 phrases)' },
      { value: 'points', label: 'Points clés (liste à puces)' },
      { value: 'structured', label: 'Résumé structuré (paragraphes)' }
    ]
  }
};

for (const param of finalRequiredParams) {
  if (!params[param] || params[param] === '') {
    missingParams.push(param);
    questions.push({
      param: param,
      ...(paramQuestions[param] || { question: `Veuillez fournir: ${param}`, type: 'text' })
    });
  }
}

return {
  json: {
    valid: missingParams.length === 0,
    can_proceed: missingParams.length === 0,
    missing: missingParams,
    errors: [],
    questions: questions,
    action: action,
    user_message: userMessage,
    params: params,
    file_url: body.file_url || '',
    file_type: body.file_type || '',
    is_custom_action: isCustomAction,
    custom_webhook_url: customActions[action]?.webhook_url || null
  }
};

